from g69_core import bars_fig, fig_formation, make_lesson, make_q, table_fig

S = 'GDTC 7'


def _q(b: int, n: int, d: str, p: str, correct: str, wrongs: list[str], e: str, h: str = '', fig=None) -> dict:
    return make_q(f'GD7-B{b:02d}-{n:03d}', d, p, correct, wrongs, e, S, h, fig)


